INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(82933935, 'Mimighoul Flower', NULL, NULL, 'Flip Effect Monster', 'Plant', 'EARTH', 1, NULL, 2100, NULL),
(19338434, 'Mimighoul Fork', '迷拟宝箱鬼・岔路', 'ミミグル・フォーク', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只里侧表示怪兽为对象才能发动。对方从以下效果选1个，自己让那个效果适用。 ●作为对象的怪兽变成表侧攻击表示或表侧守备表示。 ●作为对象的怪兽送去墓地。那之后，这个效果送去墓地的怪兽的持有者抽2张。 ②：把墓地的这张卡除外才能发动。从卡组把1张「迷拟宝箱鬼·岔路」加入手卡。'),
(13204145, 'Mimighoul Maker', '迷拟宝箱鬼・创造主', 'ミミグル・メーカー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把2只卡名不同的反转怪兽给对方观看，对方从那之中随机选1只。那1只在对方场上里侧守备表示特殊召唤，剩余加入自己手卡。那之后，可以从手卡把1只「迷拟宝箱鬼」怪兽特殊召唤。 ②：对方把怪兽特殊召唤的场合，把墓地的这张卡除外，以对方场上1只里侧表示怪兽为对象才能发动。那只怪兽变成表侧攻击表示或表侧守备表示。'),
(55537983, 'Mimighoul Master', '迷拟宝箱鬼・领主', 'ミミグル・マスター', 'Effect Monster', 'Zombie', 'EARTH', 4, 1800, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「迷拟宝箱鬼·领主」以外的1只「迷拟宝箱鬼」怪兽加入手卡。 ②：自己场上有「迷拟宝箱鬼·领主」以外的「迷拟宝箱鬼」怪兽存在的场合或者对方场上有里侧表示怪兽存在的场合，场上的这张卡不会被战斗·效果破坏。 ③：对方主要阶段才能发动。场上1只里侧表示怪兽变成表侧攻击表示或表侧守备表示。'),
(59293853, 'Mimighoul Room', '迷拟宝箱鬼・藏宝间', 'ミミグル・ルーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡·卡组选1只「迷拟宝箱鬼」怪兽在自己场上特殊召唤或在对方场上里侧守备表示特殊召唤。那之后，可以把场上1只表侧表示怪兽变成里侧守备表示。 ②：把墓地的这张卡除外，以自己场上的「迷拟宝箱鬼」卡任意数量为对象才能发动。那些卡回到手卡。'),
(80551022, 'Mimighoul Slime', '迷拟宝箱鬼・史莱姆', 'ミミグル・スライム', 'Flip Effect Monster', 'Aqua', 'EARTH', 1, 400, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡往对方场上里侧守备表示特殊召唤。对方场上的怪兽数量比自己场上的怪兽多的场合，也能作为代替在自己场上表侧表示特殊召唤。 ②：这张卡在主要阶段反转的场合发动。以下效果各适用。 ●对方可以从自身卡组把1只「迷拟宝箱鬼」怪兽特殊召唤。 ●这张卡的控制权移给对方。'),
(42940335, 'Mimighoul Throne', '迷拟宝箱鬼・王座', 'ミミグル・スローン', 'XYZ Monster', 'Rock', 'EARTH', 1, NULL, 1000, '1星「迷拟宝箱鬼」怪兽×2 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡1个超量素材取除才能发动。从自己的手卡·卡组·墓地把1只「迷拟宝箱鬼·领主」特殊召唤。 ②：自己·对方的主要阶段，以自己场上1只「迷拟宝箱鬼·领主」为对象才能发动。这张卡当作攻击力上升1000的装备魔法卡使用给那只怪兽装备。那之后，可以让最多有这张卡持有的超量素材数量的场上的卡回到手卡。'),
(74879881, 'Mimikuril', '亚克力玩偶怪', 'ミミックリル', 'Effect Monster', 'Fiend', 'DARK', 3, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：自己主要阶段才能发动。自己卡组最上面的卡翻开，那是怪兽的场合，那只怪兽特殊召唤，这张卡回到持有者卡组最下面。不是的场合或者不能特殊召唤的场合，那张卡回到卡组最下面。这个效果特殊召唤的怪兽在结束阶段回到持有者卡组最下面。'),
(45651298, 'Mimimic', '似耳怪', 'ミミミック', 'Effect Monster', 'Machine', 'EARTH', 3, 300, 300, '对方场上有怪兽存在，自己场上有3星的怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法的「似耳怪」的特殊召唤1回合只能有1次。'),
(76348260, 'Mimir of the Nordic Ascendant', '极星天 密弥尔', '極星天ミーミル', 'Effect Monster', 'Fairy', 'DARK', 2, 600, NULL, '自己场上有名字带有「极星」的怪兽表侧表示存在的场合，自己的准备阶段开始时只有1次，从手卡把1张魔法卡送去墓地才能发动。墓地存在的这张卡特殊召唤。'),
(61845881, 'Minairuka', '米那海豚', 'ミナイルカ', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：水属性怪兽的效果发动时才能发动。这张卡从手卡特殊召唤。 ②：把自己场上1只表侧表示的鱼族·海龙族·水族怪兽除外，以场上1张表侧表示卡为对象才能发动。那张卡的效果直到对方回合结束时无效。'),
(32539892, 'Minar', '伊比', 'イビー', 'Effect Monster', 'Insect', 'EARTH', 3, 850, 750, '这张卡被对方的卡的效果从手卡丢弃去墓地时，给与对方基本分1000分伤害。'),
(12172567, 'Mind Castlin', '心智易位凯瑟琳', 'マインド・キャスリン', 'Synchro Monster', 'Psychic', 'DARK', 6, 1500, 2600, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽和这张卡的控制权交换。 ②：同调召唤的这张卡被送去墓地的场合，以自己以及对方场上的表侧表示怪兽各1只为对象才能发动。那2只怪兽的控制权交换。'),
(37520316, 'Mind Control', '精神操作', '精神操作', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽不能攻击宣言，不能解放。'),
(15800838, 'Mind Crush', '心灵崩坏', 'マインドクラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：宣言1个卡名才能发动。宣言的卡在对方手卡的场合，对方把手卡的那卡全部丢弃。宣言的卡不在对方手卡的场合，自己手卡随机选1张丢弃。'),
(68937720, 'Mind Drain', '精神抽取', 'メンタルドレイン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '支付1000基本分才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，双方不能把手卡的怪兽的效果发动。'),
(75392615, 'Mind Haxorz', '心灵透视', 'マインド・ハック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分。对方的手卡和对方场上盖放的卡全部确认。'),
(96782886, 'Mind Master', '精神脑魔', 'メンタルマスター', 'Tuner Monster', 'Psychic', 'LIGHT', 1, 100, 200, '支付800基本分，把自己场上「精神脑魔」以外的1只念动力族怪兽解放发动。从自己的卡组把1只等级4以下的念动力族怪兽在自己场上以表侧攻击表示特殊召唤。'),
(66690411, 'Mind on Air', '本性暴露', 'マインド・オン・エア', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1000, 1600, '只要这张卡在场上表侧表示存在，对方必须永续公开手卡。'),
(59718521, 'Mind Over Matter', '白朗宁之力', 'ブローニング・パワー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把自己场上存在的1只念动力族怪兽解放发动。魔法·陷阱卡的发动、怪兽的召唤·特殊召唤的其中1个无效并破坏。'),
(69257165, 'Mind Pollutant', '精神污染', '精神汚染', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡丢弃1只怪兽才能发动。选择持有和那只怪兽相同等级的对方场上1只怪兽直到结束阶段时得到控制权。'),
(62606805, 'Mind Procedure', '心灵推进者', 'メンタルプロシージャー', 'Tuner Monster', 'Psychic', 'LIGHT', 3, 1100, 1100, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤或者用怪兽的效果特殊召唤的场合，支付2000基本分才能发动。从自己的卡组·墓地把1张「瞬间移动」通常·速攻魔法卡加入手卡。 ②：把自己场上的这张卡作为念动力族同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ③：这张卡被除外的场合，支付1000基本分才能发动。这张卡特殊召唤。'),
(85060248, 'Mind Protector', '心灵防护者', 'メンタルプロテクター', 'Effect Monster', 'Psychic', 'LIGHT', 3, NULL, 2200, '这张卡的控制者在每次自己的准备阶段支付500基本分。这个时候不支付500基本分的场合这张卡破坏。只要这张卡在场上表侧表示存在，念动力族怪兽以外的攻击力2000以下的怪兽不能攻击宣言。'),
(300201008, 'Mind Scan (Skill Card)', NULL, NULL, 'Skill Card', 'Pegasus', NULL, NULL, NULL, NULL, NULL),
(38680149, 'Mind Trust', '信赖之心', 'トラスト・マインド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只2星以上的怪兽解放发动。从自己墓地把1只持有解放怪兽一半以下的等级的调整加入手卡。'),
(52817046, 'Mind Wipe', '记忆抹消', '記憶抹消', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '对方手卡3张以下的场合才能发动。对方把手卡加入到卡组洗切。之后对方抽出和加入卡组的卡数量相同的卡。'),
(76321376, 'Mine Golem', '地雷石人', 'マイン・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 3, 1000, 1900, '这张卡被战斗破坏送去墓地时，给与对方基本分500分伤害。'),
(94079037, 'Mine Mole', '采矿鼹鼠', 'マイン・モール', 'Effect Monster', 'Beast', 'EARTH', 3, 1000, 1200, '这张卡1回合只有1次不会被战斗破坏。这张卡作为兽族怪兽的同调召唤的素材送去墓地的场合，从自己卡组抽1张卡。这张卡因对方的卡的效果从场上离开的场合，从游戏中除外。'),
(85519211, 'Minefield Eruption', '岩盘爆破', '岩盤爆破', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的「地雷石人」每有1只，给与对方基本分1000分的伤害。之后自己场上表侧表示存在的「地雷石人」全部破坏。'),
(24419823, 'Minefieldriller', '矿场钻机', 'マインフィールド', 'Effect Monster', 'Machine', 'EARTH', 4, 1500, 1500, '①：表侧表示的这张卡从自己场上离开时，以自己墓地1张场地魔法卡为对象才能发动。那张卡加入手卡。'),
(40164421, 'Minerva, Lightsworn Maiden', '光道少女 密涅瓦', 'ライトロード・メイデン ミネルバ', 'Tuner Monster', 'Spellcaster', 'LIGHT', 3, 800, 200, '①：这张卡召唤时才能发动。把持有自己墓地的「光道」怪兽种类数量以下的等级的1只龙族·光属性怪兽从卡组加入手卡。 ②：这张卡从手卡·卡组送去墓地的场合发动。从自己卡组上面把1张卡送去墓地。 ③：自己结束阶段发动。从自己卡组上面把2张卡送去墓地。'),
(53666449, 'Minerva, Scholar of the Sky', '天空贤者 密涅瓦', '天空賢者ミネルヴァ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 400, '①：只要这张卡在怪兽区域存在，每次自己或者对方把反击陷阱卡发动，这张卡的攻击力上升500，场上有「天空的圣域」存在的场合，再从自己墓地选和那张发动的反击陷阱卡卡名不同的1张反击陷阱卡加入手卡。'),
(18843291, 'Minerva, the Athenian Lightsworn', '光道雅典娜 密涅瓦', 'ライトロード・アテナ ミネルバ', 'Synchro Monster', 'Fairy', 'LIGHT', 8, 2800, 1800, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。把最多有那些作为同调素材的「光道」怪兽数量的「光道」怪兽从卡组送去墓地（相同种族最多1只）。 ②：自己场上的「光道」怪兽不能用效果除外。 ③：从自己墓地把最多4只「光道」怪兽除外才能发动。把除外数量的卡从自己卡组上面送去墓地。'),
(30100551, 'Minerva, the Exalted Lightsworn', '光道圣女 密涅瓦', 'ライトロード・セイント ミネルバ', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 2000, 800, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从自己卡组上面把3张卡送去墓地。那之中有「光道」卡的场合，再让自己抽出那个数量。 ②：这张卡被战斗或者对方的效果破坏的场合才能发动。从自己卡组上面把3张卡送去墓地。那之中有「光道」卡的场合，可以再把最多有那个数量的场上的卡破坏。'),
(54537490, 'Mini Mare Mare Token', '龙落亲', 'タツノオトシオヤ', 'Token', 'Wyrm', NULL, NULL, NULL, NULL, NULL),
(99004752, 'Mini-Guts', '迷你胆识', 'ミニマム・ガッツ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只怪兽解放，选择对方场上表侧表示存在的1只怪兽才能发动。选择的怪兽的攻击力直到结束阶段时变成0。这个回合，选择的怪兽被战斗破坏送去对方墓地时，给与对方基本分那只怪兽的原本攻击力数值的伤害。'),
(34815282, 'Miniaturize', '迷你化', 'ミニチュアライズ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只原本攻击力比1000高的怪兽发动。选择怪兽的等级下降1星，攻击力下降1000。那只怪兽不在场上存在时，这张卡破坏。'),
(73341839, 'Miniborrel Dragon', '短枪管龙', 'ショートヴァレル・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 800, NULL, '「弹丸」怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己场上有「枪管」连接怪兽存在的场合，把自己场上1只连接3以下的怪兽解放才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡不能作为连接标记数量和解放的怪兽相同的怪兽的连接素材。'),
(21147203, 'Minimalian', '极简小星人', 'ミニマリアン', 'Effect Monster', 'Psychic', 'WATER', 4, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从手卡把1张其他卡除外才能发动。这张卡特殊召唤。 ②：把自己场上1只4星以下的表侧表示怪兽除外才能发动。原本等级比除外的怪兽低1星或2星并原本的种族·属性相同的1只怪兽从卡组特殊召唤。'),
(43708640, 'Minoan Centaur', '牛马林神', 'ミノケンサテュロス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 6, 1800, 1000, '这张卡不能特殊召唤。可以把这张卡解放，从自己卡组把2只兽战士族·4星的通常怪兽特殊召唤。'),
(46864967, 'Minomushi Warrior', '岩之战士', '岩の戦士', 'Normal Monster', 'Rock', 'EARTH', 4, 1300, 1200, '岩石战士。挥舞着非常重的石头剑。'),
(1918087, 'Minor Goblin Official', '哥布林小役人', 'ゴブリンの小役人', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的基本分3000以下的场合才可以发动。每次对方的准备阶段对方基本分受到500分的伤害。'),
(44201739, 'Mira Match', '米乐与磷寸之仔', 'ミラァと燐寸之仔', 'Effect Monster', 'Spellcaster', 'FIRE', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。同名卡在对方墓地存在的3张卡从手卡·卡组给对方观看（同名卡最多1张），这张卡特殊召唤。 ②：对方把魔法·陷阱·怪兽的效果发动时，把这张卡的①的效果特殊召唤的这张卡送去墓地才能发动。把1张对方发动的那张卡的同名卡从卡组·额外卡组送去墓地，那个发动无效。'),
(60181553, 'Mira the Star-Bearer', '巨星之米拉', '巨星のミラ', 'XYZ Monster', 'Warrior', 'LIGHT', 1, 1100, 1000, '1星怪兽×3 场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡1个超量素材取除。此外，只要这张卡在场上表侧表示存在，自己场上表侧表示存在的4星以下的怪兽不会被卡的效果破坏。'),
(35255456, 'Miracle Contact', '奇迹接触', 'ミラクル・コンタクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上·墓地让融合怪兽卡决定的融合素材怪兽回到持有者卡组，把以「元素英雄 新宇侠」为融合素材的那1只「元素英雄」融合怪兽无视召唤条件从额外卡组特殊召唤。'),
(6343408, 'Miracle Dig', '奇迹之发掘', '奇跡の発掘', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：除外的自己怪兽5只以上存在的场合，以那之内3只为对象才能发动。那些怪兽回到墓地。'),
(30875635, 'Miracle Ejector', '奇迹除外士', 'ミラクル・エクスクルーダー', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 400, 400, '这个卡名在规则上也当作「元素英雄」卡使用。这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从卡组把1只「新空间侠」怪兽送去墓地才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把有「元素英雄」怪兽的卡名记述的1张魔法·陷阱卡加入手卡。 ③：这张卡被送去墓地的场合，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(44887817, 'Miracle Fertilizer', '增草剂', '増草剤', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以自己墓地1只植物族怪兽为对象才能发动。那只植物族怪兽特殊召唤。这个效果把怪兽特殊召唤的回合，自己不能通常召唤。这个效果特殊召唤的怪兽从场上离开时这张卡破坏。'),
(131182, 'Miracle Flipper', '奇迹反转士', 'ミラクル・フリッパー', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 300, 500, '「奇迹反转士」在自己场上存在的场合，这张卡不能召唤·反转召唤·特殊召唤。只要这张卡在场上表侧表示存在，对方不能选择其他的表侧表示的怪兽作为攻击对象。这张卡被战斗破坏的场合，这张卡在对方场上特殊召唤。这张卡被魔法·陷阱的效果破坏的场合，把对方场上1只怪兽破坏。'),
(45906428, 'Miracle Fusion', '奇迹结合', 'ミラクル・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的场上·墓地的怪兽作为融合素材除外，把1只「元素英雄」融合怪兽融合召唤。'),
(63259351, 'Miracle Jurassic Egg', '奇迹的侏罗纪蛋', '奇跡のジュラシック・エッグ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, NULL, 2000, '①：场上的表侧表示的这张卡不能除外。 ②：只要这张卡在怪兽区域存在，每次恐龙族怪兽被送去自己墓地，给这张卡放置2个指示物。 ③：把这张卡解放才能发动。把持有这张卡放置的指示物数量以下的等级的1只恐龙族怪兽从卡组特殊召唤。'),
(55985014, 'Miracle Kids', '奇迹小子', 'ミラクル・キッズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '直到结束阶段前，对方的1只怪兽的攻击力下降自己墓地存在的「英雄小子」的数量×400的数值。'),
(97168905, 'Miracle Locus', '奇迹之轨迹', '奇跡の軌跡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧攻击表示存在的1只怪兽发动。对方从卡组抽1张卡。直到这个回合的结束阶段时，选择怪兽的攻击力上升1000，同1次的战斗阶段中最多2次可以向怪兽攻击。那只怪兽进行战斗的场合，对方玩家受到的战斗伤害变成0。'),
(40456412, 'Miracle of the Supreme King', '霸王龙之奇迹', '覇王龍の奇跡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「霸王龙 扎克」存在的场合，可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己场上1张「霸王龙 扎克」破坏，从卡组·额外卡组把1只「异色眼」灵摆怪兽或者光属性「霸王龙 扎克」无视召唤条件特殊召唤。 ●自己的额外卡组1只表侧的灵摆怪兽在自己的灵摆区域放置。 ●从卡组把1张速攻魔法卡在自己场上盖放。'),
(18988396, 'Miracle Raven', '奇迹的供物', NULL, 'Pendulum Effect Ritual Monster', 'Fiend', 'DARK', 1, 300, 300, '「奇迹的供物」降临。 这张卡不用仪式召唤不能特殊召唤。 仪式召唤的这张卡不受对方发动的效果影响。 仪式怪兽1只仪式召唤的场合，可以用自己场上的这1张卡作为仪式召唤需要的数值的解放使用。 这张卡为仪式召唤而解放的场合：可以从卡组把1只仪式怪兽加入手卡。「奇迹的供物」的这个效果1回合只能使用1次。'),
(68334074, 'Miracle Restoring', '奇迹之复活', '奇跡の復活', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上2个魔力指示物取除才能发动。从自己墓地选择1只「黑魔术师」或者「破坏之剑士」特殊召唤。'),
(44297127, 'Miracle Rupture', '奇迹之穿孔', '奇跡の穿孔', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只4星以下的岩石族怪兽送去墓地。自己墓地有「化石融合」存在的场合，再让自己从卡组抽1张。'),
(31461282, 'Miracle Stone', '开运奇迹石', '開運ミラクルストーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「开运奇迹石」在自己场上只能有1张表侧表示存在。 ②：自己场上的魔法师族怪兽的攻击力·守备力上升自己场上的「占卜魔女」怪兽种类×500。 ③：1回合1次，自己的「占卜魔女」怪兽进行战斗的攻击宣言时才能发动。自己从卡组抽1张。'),
(36484016, 'Miracle Synchro Fusion', '奇迹同步结合', 'ミラクルシンクロフュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的场上·墓地把融合怪兽卡决定的融合素材怪兽除外，把以同调怪兽为融合素材的那1只融合怪兽从额外卡组融合召唤。 ②：盖放的这张卡被对方的效果破坏送去墓地的场合发动。自己从卡组抽1张。'),
(21636650, 'Miracle''s Wake', '奇迹之残照', '奇跡の残照', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以这个回合被战斗破坏送去自己墓地的1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(80551130, 'Miraculous Descent', '奇迹之光临', '奇跡の光臨', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以除外的1只自己的天使族怪兽为对象才能把这张卡发动。那只怪兽特殊召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(37011715, 'Miraculous Rebirth', '奇迹之苏生', '奇跡の蘇生', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '连锁4以后才能发动。从墓地选择1只怪兽，在自己场上特殊召唤。同1组连锁上有复数次同名卡的效果发动的场合，这张卡不能发动。'),
(15960641, 'Mirage Dragon', '幻象龙', 'ミラージュ・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1600, 600, '①：只要这张卡在怪兽区域存在，对方在战斗阶段不能把陷阱卡发动。'),
(49217579, 'Mirage Knight', '幻影之骑士', '幻影の騎士－ミラージュ・ナイト－', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 2000, '这张卡不能通常召唤，用「黑炎之骑士」的效果才能特殊召唤。 ①：这张卡的攻击力只在和对方怪兽进行战斗的伤害计算时上升那只对方怪兽的原本攻击力数值。 ②：这张卡进行战斗的回合的结束阶段发动。这张卡除外。'),
(52607696, 'Mirage Mirror Force', '幻惑防护罩－迷幻镜力－', '幻惑のバリア －ミラージュフォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时才能发动。从自己的手卡·墓地把1只幻想魔族怪兽特殊召唤，那只攻击怪兽回到手卡。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的幻想魔族怪兽因对方的效果从场上离开的场合，把这张卡除外才能发动。从自己的手卡·墓地把1只幻想魔族怪兽特殊召唤。'),
(41482598, 'Mirage of Nightmare', '噩梦之蜃气楼', '悪夢の蜃気楼', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的准备阶段时，自己抽卡直到4张手卡。自己的准备阶段时，随机丢弃那个效果所抽的卡的数量的手卡。'),
(73936388, 'Mirage Swordsman', '幻炎之剑士', '幻炎の剣士－ミラージュ・ソードマン－', 'Effect Monster', 'Warrior', 'FIRE', 8, 2800, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上的表侧表示的炎属性融合怪兽被战斗·效果破坏的场合才能发动。这张卡从手卡·墓地特殊召唤。 ②：这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那2只进行战斗的怪兽破坏。 ③：这张卡被战斗或者其他卡的效果破坏的场合才能发动。7星以下的1只「炎之剑士」或者有那个卡名记述的怪兽从卡组·额外卡组特殊召唤。'),
(63442605, 'Mirage Token', '物理分身', '物理分身', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(48017809, 'Mirage Tube', '蜃气楼之筒', '蜃気楼の筒', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡不能从手卡发动。自己场上表侧表示存在的怪兽被选择作为攻击对象时才能发动。给与对方基本分1000分伤害。'),
(95915457, 'Mirror Barrier', '镜罩', 'ミラーバリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能把这张卡发动。这张卡当作持有以下效果的装备卡使用给那只怪兽装备。 ●装备怪兽和对方怪兽进行战斗的战斗步骤才能发动1次。那只对方怪兽破坏。 ②：这张卡被破坏的场合才能发动。从卡组把1张「武装转生」加入手卡。'),
(44095762, 'Mirror Force', '神圣防护罩－反射镜力－', '聖なるバリア －ミラーフォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方场上的攻击表示怪兽全部破坏。'),
(84687358, 'Mirror Force Dragon', '反射镜力龙', 'ミラーフォース・ドラゴン', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 2800, 1200, '这张卡在用「克里底亚之牙」的效果把自己的手卡·场上的「神圣防护罩 -反射镜力-」送去墓地的场合才能特殊召唤。 ①：自己场上的怪兽被选择作为攻击对象时或者成为对方的效果的对象时才能发动。对方场上的卡全部破坏。'),
(29649320, 'Mirror Force Launcher', '反射镜力启动', 'ミラーフォース・ランチャー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段从手卡丢弃1只怪兽才能发动。从自己的卡组·墓地选1张「神圣防护罩 -反射镜力-」加入手卡。 ②：盖放的这张卡被对方的效果破坏送去墓地的场合才能发动。选墓地的这张卡和自己的手卡·卡组·墓地1张「神圣防护罩 -反射镜力-」，那张卡和这张卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(43452193, 'Mirror Gate', '异次元隧道-镜之门-', '異次元トンネル－ミラーゲート－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「元素英雄」的怪兽为攻击对象的对方怪兽攻击宣言时才能发动。对方的攻击怪兽和成为攻击对象的自己怪兽交换控制权进行伤害计算。直到这个回合结束阶段时得到控制权交换怪兽的控制权。'),
(45358284, 'Mirror Ladybug', '镜瓢虫', 'ミラー・レディバグ', 'Effect Monster', 'Insect', 'LIGHT', 1, 100, 100, '自己场上有表侧表示怪兽1只以上存在，自己墓地没有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个效果特殊召唤成功时，这张卡的等级变成这张卡以外的自己场上存在的怪兽的等级合计的等级。此外，场上表侧表示存在的这张卡的等级超过12的场合，这张卡破坏。'),
(9396662, 'Mirror Mage of the Ice Barrier', '冰结界的镜魔师', '氷結界の鏡魔師', 'Tuner Monster', 'Aqua', 'WATER', 2, 1000, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只其他的效果怪兽解放才能发动。在自己场上把最多3只「冰结界衍生物」（水族·水·1星·攻/守0）特殊召唤，这张卡的等级上升那个数量的数值。这个回合，自己不是水属性同调怪兽不能从额外卡组特殊召唤。 ②：这张卡被送去墓地的场合才能发动。「冰结界的镜魔师」以外的自己的卡组·除外状态的1张「冰结界」卡加入手卡。'),
(67232306, 'Mirror Mail', '神圣之铠 -反射镜甲-', '聖なる鎧 －ミラーメール－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的怪兽被选择作为攻击对象时才能发动。攻击对象怪兽的攻击力变成和攻击怪兽的攻击力相同。'),
(46656406, 'Mirror of Oaths', '咒言之镜', '呪言の鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方从卡组把怪兽特殊召唤时才能发动。那些怪兽破坏，从自己卡组抽1张卡。'),
(10691144, 'Mirror of the Ice Barrier', '冰结界之镜', '氷結界の鏡', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：这个回合中，每次对方发动的怪兽的效果让卡被除外，以那卡从哪里除外来对应的以下效果适用。 ●自己手卡：对方手卡随机最多2张除外。 ●自己场上：对方场上最多2张卡除外。 ●自己墓地：对方墓地最多2张卡除外。'),
(1200843, 'Mirror of Yata', '八汰镜', '八汰鏡', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '灵魂怪兽才能装备。装备怪兽在结束阶段时回到手卡效果可以不发动。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。'),
(40159926, 'Mirror Resonator', '镜共鸣者', 'ミラー・リゾネーター', 'Tuner Monster', 'Fiend', 'LIGHT', 1, NULL, NULL, '「镜子共鸣者」的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，从额外卡组特殊召唤的怪兽只有对方场上才存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。这张卡在这个回合作为同调素材的场合，当作和作为对象的怪兽的原本等级相同等级使用。'),
(28954097, 'Mirror Swordknight', '镜 剑骑士', 'ミラー ソードナイト', 'Effect Monster', 'Illusion', 'LIGHT', 4, 1900, 300, '这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡解放才能发动。把「镜剑骑士」以外的有「合成兽融合」的卡名记述的1只怪兽从卡组特殊召唤。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：自己场上有「有翼幻兽 奇美拉」存在，对方场上的怪兽把效果发动时，把场上·墓地的这张卡除外才能发动。那个效果无效。'),
(22359980, 'Mirror Wall', '银幕之镜壁', '銀幕の鏡壁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己准备阶段支付2000基本分。或者不支付基本分让这张卡破坏。 ①：只要这张卡在魔法与陷阱区域存在，对方的攻击怪兽的攻击力变成一半。'),
(44146295, 'Mirrorjade the Iceblade Dragon', '冰剑龙 镜翠幻种', '氷剣竜ミラジェイド', 'Fusion Monster', 'Wyrm', 'DARK', 8, 3000, 2500, '「阿不思的落胤」＋融合·同调·超量·连接怪兽 ①：「冰剑龙 幻冰龙」在自己场上只能有1张表侧表示存在。 ②：自己·对方回合1次，把以「阿不思的落胤」为融合素材的1只融合怪兽从额外卡组送去墓地才能发动。场上1只怪兽除外。下个回合，这张卡不能使用这个效果。 ③：融合召唤的这张卡因对方从场上离开的场合才能发动。这个回合的结束阶段，对方场上的怪兽全部破坏。'),
(33178416, 'Misairuzame', '奈耳', 'ナイル', 'Normal Monster', 'Fish', 'WATER', 5, 1400, 1600, '全身长着针的鱼，从腹部下面发射导弹。'),
(38572779, 'Miscellaneousaurus', '幻创之混拼恐龙', '幻創のミセラサウルス', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1800, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：自己·对方的主要阶段，把这张卡从手卡送去墓地才能发动。这次主要阶段中，自己场上的恐龙族怪兽不受对方发动的效果影响。 ②：从自己墓地把包含这张卡的恐龙族怪兽任意数量除外才能发动。把持有和除外的怪兽数量相同等级的1只恐龙族怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(164710, 'Mischief of the Gnomes', '小人的恶作剧', '小人のいたずら', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，双方手卡的怪兽的等级下降1星。 ②：把墓地的这张卡除外才能发动。这个回合，双方手卡的怪兽的等级下降1星。'),
(92182447, 'Mischief of the Time Goddess', '时间女神的恶作剧', '時の女神の悪戯', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡不能连锁发动，不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。 ①：自己场上的怪兽只有「女武神」怪兽的场合，自己战斗阶段结束时才能发动。这张卡送去墓地。把回合跳到下次的自己回合的战斗阶段开始时。直到那个回合的结束时自己不能把「时间女神的恶作剧」发动。'),
(101303083, 'Mischief of the Wolves', NULL, NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, NULL),
(29795530, 'Mischief of the Yokai', '妖怪的恶作剧', '妖怪のいたずら', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的全部怪兽的等级直到回合结束时下降2星。 ②：把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的等级直到回合结束时下降1星。这个效果在这张卡送去墓地的回合不能发动。'),
(1036974, 'Misfortune', '不幸', 'ミスフォーチュン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上表侧表示存在的1只怪兽发动。给与对方基本分选择的怪兽的原本攻击力一半的伤害。使用这个效果的回合，自己的怪兽不能攻击。'),
(28115467, 'MiSolfachord Eliteia', '咪音服和弦・爱理迪娅', 'ミドレミコード・エリーティア', 'Pendulum Effect Monster', 'Fairy', 'WATER', 3, 1100, 400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到持有者手卡。 ②：只要自己的灵摆区域有偶数的灵摆刻度存在，自己的「七音服」灵摆怪兽的战斗发生的对自己的战斗伤害变成0。'),
(58392024, 'Mispolymerization', '融合失败', '融合失敗', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '融合怪兽特殊召唤时发动。场上存在的融合怪兽全部回到融合卡组。'),
(12836042, 'Missing Force', '落单佣兵部队', 'はぐれ者傭兵部隊', 'Effect Monster', 'Warrior', 'DARK', 4, 1500, 1000, '自己场上没有这张卡以外的怪兽存在的场合，把这张卡解放才能发动。选择对方场上1只怪兽直到结束阶段时得到控制权。这个效果发动的回合，自己不能把怪兽特殊召唤，不能进行战斗阶段。'),
(3987233, 'Missus Radiant', '金毛女士', 'ミセス・レディエント', 'Link Monster', 'Beast', 'EARTH', NULL, 1400, NULL, '地属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：场上的地属性怪兽的攻击力·守备力上升500，风属性怪兽的攻击力·守备力下降400。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只地属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(28601770, 'Mist Archfiend', '迷雾恶魔', 'ミストデーモン', 'Effect Monster', 'Fiend', 'DARK', 5, 2400, NULL, '①：这张卡可以不用解放作召唤。 ②：这张卡的①的方法召唤的场合，结束阶段发动。这张卡破坏，自己受到1000伤害。'),
(15240238, 'Mist Bird Clausolas', '霞鸟 辉剑鸟', '霞鳥クラウソラス', 'Synchro Monster', 'Winged Beast', 'WIND', 3, NULL, 2300, '调整＋调整以外的怪兽1只以上 1回合1次，选择对方场上表侧表示存在的1只怪兽才能发动。直到回合结束时选择的怪兽的攻击力变成0，那个效果无效。'),
(47529357, 'Mist Body', '雾状躯体', 'ミスト・ボディ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽不会被战斗破坏。'),
(65549080, 'Mist Condor', '霞雾秃鹰', 'ミスト・コンドル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 400, '这张卡可以让自己场上表侧表示存在的1只名字带有「霞之谷」的怪兽回到手卡，从手卡特殊召唤。这个方法特殊召唤的这张卡的攻击力变成1700。'),
(29587993, 'Mist Valley Apex Avian', '霞之谷的巨神鸟', '霞の谷の巨神鳥', 'Effect Monster', 'Winged Beast', 'WIND', 7, 2700, 2000, '这张卡的效果在同一连锁上只能发动1次。 ①：魔法·陷阱·怪兽的效果发动时，以自己场上1张「霞之谷」卡为对象才能发动。那张自己的「霞之谷」卡回到持有者手卡，那个发动无效并破坏。'),
(14983497, 'Mist Valley Baby Roc', '霞之谷的幼怪鸟', '霞の谷の幼怪鳥', 'Tuner Monster', 'Winged Beast', 'WIND', 2, 400, 600, '①：这张卡从手卡送去墓地时才能发动。这张卡特殊召唤。'),
(41978142, 'Mist Valley Executor', '霞之谷的执行者', '霞の谷の執行者', 'Effect Monster', 'Thunder', 'WIND', 5, 2100, 1600, '这张卡召唤成功时，场上表侧表示存在的魔法·陷阱卡全部回到持有者手卡。'),
(82199284, 'Mist Valley Falcon', '霞之谷的猎鹰', '霞の谷のファルコン', 'Effect Monster', 'Winged Beast', 'WIND', 4, 2000, 1200, '这张卡若不让自己场上存在的1张卡回到手卡则不能攻击宣言。'),
(95443805, 'Mist Valley Shaman', '霞之谷的祈祷师', '霞の谷の祈祷師', 'Tuner Monster', 'Winged Beast', 'WIND', 3, 1200, 1200, '可以让自己场上的这张卡以外的1只怪兽回到手卡，这张卡的攻击力直到结束阶段时上升500。这个效果1回合只能使用1次。'),
(22837504, 'Mist Valley Soldier', '霞之谷的战士', '霞の谷の戦士', 'Tuner Monster', 'Winged Beast', 'WIND', 4, 1700, 300, '只要这张卡在自己场上表侧表示存在，和这张卡的战斗没被破坏的对方怪兽在伤害步骤结束时回到持有者手卡。'),
(89310929, 'Mist Valley Thunder Lord', '霞之谷的雷神鬼', '霞の谷の雷神鬼', 'Synchro Monster', 'Thunder', 'WIND', 7, 2600, 2400, '调整＋调整以外的名字带有「霞之谷」的怪兽1只以上 1回合1次，选择这张卡以外的自己场上1张卡才能发动。选择的自己的卡回到持有者手卡，这张卡的攻击力直到结束阶段时上升500。这个效果在对方回合也能发动。'),
(69448290, 'Mist Valley Thunderbird', '霞之谷的雷鸟', '霞の谷の雷鳥', 'Effect Monster', 'Thunder', 'WIND', 3, 1100, 700, '场上表侧表示存在的这张卡回到手卡时，这张卡在自己场上特殊召唤。这个效果特殊召唤成功的回合，这张卡不能进行攻击。'),
(29054481, 'Mist Valley Watcher', '霞之谷的看守者', '霞の谷の見張り番', 'Normal Monster', 'Spellcaster', 'WIND', 4, 1500, 1900, '世世代代一直看守霞之谷的看守者一族的后裔。只要是在谷里发生的事，再怎么微不足道的事情也逃不出他的双眼。'),
(92933195, 'Mist Valley Windmaster', '霞之谷的风使', '霞の谷の風使い', 'Tuner Monster', 'Winged Beast', 'WIND', 2, 400, 800, '双方手卡有5张以上的场合才能发动。双方玩家直到手卡变成4张把手卡送去墓地。这个效果1回合只能使用1次。'),
(27315304, 'Mist Wurm', '喷霞虫', 'ミスト・ウォーム', 'Synchro Monster', 'Thunder', 'WIND', 9, 2500, 1500, '调整＋调整以外的怪兽2只以上 ①：这张卡同调召唤成功的场合，以对方场上最多3张卡为对象发动。那些对方的卡回到持有者手卡。'),
(59305593, 'Mistake', '搭错', '手違い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方不能用抽卡以外的方法从卡组把卡加入手卡。'),
(89883517, 'Mistaken Accusation', '冤枉', '濡れ衣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「冤枉」在1回合只能发动1张。 ①：对方的手卡·场上的卡合计数量比自己的手卡·场上的卡合计数量多的场合，以场上1张表侧表示的卡为对象才能发动。双方玩家在这次决斗中不能把那张表侧表示的卡以外的和作为对象的卡同名卡的效果发动。'),
(4227096, 'Mistaken Arrest', '抓错', '捕違い', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：这张卡的发动后，直到下次的自己回合的结束时，双方不能用抽卡以外的方法从卡组把卡加入手卡。'),
(65170459, 'Mistar Boy', '海星男士', 'マスター・ボーイ', 'Link Monster', 'Aqua', 'WATER', NULL, 1400, NULL, '水属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：场上的水属性怪兽的攻击力·守备力上升500，炎属性怪兽的攻击力·守备力下降400。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只水属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(22404675, 'Mithra the Thunder Vassal', '雷帝家臣密斯拉', '雷帝家臣ミスラ', 'Effect Monster', 'Thunder', 'LIGHT', 2, 800, 1000, '「雷帝家臣 密特拉」的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡特殊召唤，在对方场上把1只「家臣衍生物」（雷族·光·1星·攻800/守1000）守备表示特殊召唤。这个回合，自己不能从额外卡组把怪兽特殊召唤。 ②：这张卡为上级召唤而被解放的场合才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以上级召唤。'),
(67282505, 'Mitsu the Insect Ninja', '虫之忍者-蜜', '蟲の忍者－蜜', 'Effect Monster', 'Insect', 'WATER', 2, 200, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「忍者」卡或者里侧守备表示怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：对方把怪兽的效果发动时，以自己场上1只里侧守备表示怪兽为对象才能发动。那只怪兽变成表侧守备表示，这张卡变成里侧守备表示。作为对象的怪兽是「虫之忍者-蜜」以外的「忍者」怪兽的场合，再把那个对方的所发动的效果无效。'),
(17954937, 'Mitsurugi Great Purification', '巳剑大祓', '巳剣大祓', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：对方把魔法·陷阱·怪兽的效果发动时，把自己场上1只5星以上的爬虫类族怪兽解放才能发动。那个效果无效并破坏。 ②：把墓地的这张卡除外，以自己墓地1只爬虫类族怪兽为对象才能发动。那只怪兽特殊召唤，这个效果特殊召唤的怪兽以外的自己场上1只怪兽解放。'),
(76725398, 'Mitsurugi Magatama', '巳剑之勾玉', '巳剣之勾玉', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，可以从以下效果选择1个发动。 ●把自己场上1只爬虫类族怪兽解放，以对方场上1张表侧表示卡为对象才能发动。那张卡破坏。 ●等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己场上的怪兽解放，从手卡把1只「巳剑」仪式怪兽仪式召唤。'),
(49721684, 'Mitsurugi Mirror', '巳剑之神镜', '巳剣之神鏡', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的爬虫类族怪兽解放，从自己的手卡·墓地把1只爬虫类族仪式怪兽仪式召唤。 ②：这张卡在墓地存在的状态，自己场上的「天丛云之巳剑」「布都御魂之巳剑」「天羽羽斩之巳剑」的其中任意种被解放的场合才能发动。这张卡回到卡组。'),
(76948970, 'Mitsurugi no Miko, Wousu', '巳剑之皇子 小碓', '巳剣之皇子 小碓', 'Effect Monster', 'Reptile', 'DARK', 8, 2000, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把手卡1只其他的爬虫类族怪兽和对方场上1只怪兽解放，从手卡特殊召唤。这个方法特殊召唤过的回合自己不是爬虫类族怪兽不能特殊召唤，不能把爬虫类族以外的怪兽的效果发动。 ②：这张卡被解放的场合才能发动。选自己1张手卡丢弃，这张卡加入手卡。'),
(40543231, 'Mitsurugi no Mikoto, Aramasa', '巳剑之尊 麁正', '巳剣之尊 麁正', 'Effect Monster', 'Reptile', 'DARK', 4, 1200, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合或者这张卡被解放的场合才能发动。从卡组把「巳剑之尊 麁正」以外的1只「巳剑」怪兽加入手卡。 ②：自己场上的其他的爬虫类族怪兽被战斗·效果破坏的场合，可以作为代替把场上的这张卡解放。'),
(82782870, 'Mitsurugi no Mikoto, Kusanagi', '巳剑之尊 草那艺', '巳剣之尊 草那藝', 'Effect Monster', 'Reptile', 'DARK', 4, 1600, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合或者这张卡被解放的场合，以「巳剑之尊 草那艺」以外的自己的墓地·除外状态的1张「巳剑」卡为对象才能发动。那张卡加入手卡。 ②：自己场上的其他的爬虫类族怪兽被战斗·效果破坏的场合，可以作为代替把场上的这张卡解放。'),
(18176525, 'Mitsurugi no Mikoto, Saji', '巳剑之尊 佐士', '巳剣之尊 佐士', 'Effect Monster', 'Reptile', 'DARK', 4, 1000, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合或者这张卡被解放的场合才能发动。从卡组把1张「巳剑」魔法·陷阱卡加入手卡。 ②：自己场上的其他的爬虫类族怪兽被战斗·效果破坏的场合，可以作为代替把场上的这张卡解放。'),
(45171524, 'Mitsurugi Prayers', '巳剑劝请', '巳剣勧請', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己的手卡·场上1只爬虫类族怪兽解放来发动。 ①：从以下效果选1个适用。把怪兽解放来把这张卡发动的场合，可以选两方适用。 ●从卡组把1只「巳剑」怪兽加入手卡。 ●自己受到800伤害。那之后，可以从自己的手卡·墓地把1只「巳剑」怪兽特殊召唤。这个效果特殊召唤的怪兽不能直接攻击。'),
(81560239, 'Mitsurugi Ritual', '巳剑降临', '巳剣降臨', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的爬虫类族怪兽解放，从卡组把1只爬虫类族仪式怪兽仪式召唤。 ●等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·卡组·场上最多2只爬虫类族怪兽解放，从手卡把1只爬虫类族仪式怪兽仪式召唤。'),
(12210097, 'Mitsurugi Sacred Boundary', '巳剑之磐境', '巳剣之磐境', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方不能把自己场上的「巳剑」仪式怪兽作为从额外卡组特殊召唤的怪兽的效果的对象。 ②：以「巳剑之磐境」以外的自己墓地4张「巳剑」卡为对象才能发动。那些卡回到卡组。对方场上有怪兽存在的场合，再让对方必须把自身场上1只怪兽解放。'),
(49604192, 'Mitsurugi Tempest', '八云断巳剑', '八雲断巳剣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己墓地有「巳剑」仪式魔法卡存在的场合，把原本卡名是「天丛云之巳剑」「布都御魂之巳剑」「天羽羽斩之巳剑」的自己场上的怪兽各1只解放才能发动。对方必须从自身的手卡·额外卡组·场上·墓地把合计8张卡除外。'),
(71340250, 'Mixeroid', '搅拌机人', 'ミキサーロイド', 'Effect Monster', 'Machine', 'WIND', 4, NULL, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只机械族怪兽解放才能发动。从卡组把1只风属性以外的「机人」怪兽特殊召唤。 ②：把基本分支付一半，从自己墓地把包含这张卡的机械族怪兽任意数量除外才能发动。和除外的怪兽数量相同等级的1只「机人」融合怪兽从额外卡组无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(45159319, 'Moai Interceptor Cannons', '石像迎击炮', 'モアイ迎撃砲', 'Effect Monster', 'Rock', 'EARTH', 4, 1100, 2000, '这张卡1个回合1次可以变成里侧守备表示。'),
(4929256, 'Mobius the Frost Monarch', '冰帝莫比乌斯', '氷帝メビウス', 'Effect Monster', 'Aqua', 'WATER', 6, 2400, 1000, '①：这张卡上级召唤成功时，以场上最多2张魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(23689697, 'Mobius the Mega Monarch', '冻冰帝莫比乌斯', '凍氷帝メビウス', 'Effect Monster', 'Aqua', 'WATER', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。这张卡上级召唤成功时，可以选择场上最多3张魔法·陷阱卡破坏。这张卡把水属性怪兽解放作上级召唤成功的场合，那个时候的效果加上以下效果。 ●对方不能对应这个效果的发动把选择的卡发动。'),
(9861795, 'Mogmole', '遁地鼹鼠', 'モグモール', 'Effect Monster', 'Beast', 'EARTH', 2, 800, 800, '场上的这张卡被破坏送去墓地时，这张卡可以从墓地表侧守备表示特殊召唤。「遁地鼹鼠」的效果在决斗中只能使用1次。'),
(66736715, 'Moissa Knight, the Comet General', '彗圣壹将－莫桑骑士', '彗聖の将－ワンモア・ザ・ナイト', 'Pendulum Effect Monster', 'Warrior', 'LIGHT', 1, 100, 100, '①：把这张卡抽到时，把这张卡给对方观看才能发动。这个回合，自己在通常的灵摆召唤外加上只有1次，自己主要阶段可以从手卡把怪兽灵摆召唤。'),
(19093698, 'Moissa Wight', '莫桑壹白骨', 'ワンモア・ザ・ワイト', 'Effect Monster', 'Zombie', 'DARK', 1, 300, 200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在墓地存在当作「白骨」使用。 ②：这张卡召唤·特殊召唤的场合才能发动。把「翌夜之白骨骑士」以外的1只「白骨」或者1张有那个卡名记述的卡从卡组加入手卡。这个回合，自己不是不死族怪兽不能特殊召唤。 ③：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只4星以下的不死族怪兽召唤。'),
(75285069, 'Moisture Creature', '莫伊斯彻星人', 'モイスチャー星人', 'Effect Monster', 'Fairy', 'LIGHT', 9, 2800, 2900, '用3只怪兽做这张卡的召唤祭品召唤的场合，对方场上的全部魔法·陷阱破坏。'),
(94878265, 'Moja', '毛扎', 'モジャ', 'Effect Monster', 'Beast', 'EARTH', 1, 100, 100, '这张卡被战斗破坏并送去墓地时，可以把自己墓地存在的1只4星的兽族怪兽加入手卡。'),
(27288416, 'Mokey Mokey', '悠悠', 'もけもけ', 'Normal Monster', 'Fairy', 'LIGHT', 1, 300, 100, '一点也搞不明白究竟在想什么的孤僻天使。偶尔生起气来很恐怖。'),
(99910751, 'Mokey Mokey Adrift', '落单悠悠', 'はぐれ・もけもけ', 'Effect Monster', 'Fairy', 'LIGHT', 1, 300, 100, '①：这张卡只要在场上·墓地存在，卡名变成「悠悠」，当作通常怪兽使用。 ②：把这张卡从手卡丢弃才能发动。从卡组把「落单悠悠」以外的1张「悠悠」卡加入手卡。'),
(13803864, 'Mokey Mokey King', '悠悠王', 'キング・もけもけ', 'Fusion Monster', 'Fairy', 'LIGHT', 6, 300, 100, '「悠悠」＋「悠悠」＋「悠悠」 这张卡从场上离开时，可以把自己墓地存在的「悠悠」尽可能多的特殊召唤。'),
(1965724, 'Mokey Mokey Smackdown', '愤怒的悠悠', '怒れるもけもけ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「悠悠」在自己场上表侧表示存在时，自己场上天使族怪兽被破坏的场合，这个回合的结束阶段前自己场上「悠悠」的攻击力变为3000。'),
(85401123, 'Mokomoko', '毛可毛可', 'モコモッコ', 'Flip Effect Monster', 'Illusion', 'WATER', 1, 300, 300, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示。 ③：这张卡反转的场合发动。自己抽1张。'),
(17192817, 'Molten Behemoth', '熔岩大巨人', '溶岩大巨人', 'Normal Monster', 'Pyro', 'FIRE', 5, 1000, 2200, '从熔岩大地诞生的巨人。使用熔岩拳击攻击。'),
(72142276, 'Molten Conduction Field', '炎热传导场', '炎熱伝導場', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把2只「熔岩」怪兽送去墓地。'),
(19384334, 'Molten Destruction', '燃烧熔岩', 'バーニングブラッド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的炎属性的怪兽攻击力上升500，守备力下降400。'),
(37436476, 'Molten Whirlwind Wall', '炎热旋风壁', '炎熱旋風壁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「熔岩」的怪兽的攻击力上升自己墓地存在的名字带有「熔岩」的怪兽数量×100的数值。'),
(4732017, 'Molten Zombie', '灼热僵尸', '灼熱ゾンビ', 'Effect Monster', 'Pyro', 'FIRE', 4, 1600, 400, '这张卡从墓地的特殊召唤成功时，自己从卡组抽1张卡。'),
(95784434, 'Molting Escape', '蜕皮逃生', 'モルティング・エスケープ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '爬虫类族怪兽才能装备。装备怪兽1回合只有1次不会被战斗破坏。这个效果适用的伤害步骤结束时，装备怪兽的攻击力上升300。'),
(7225792, 'Mon Larvas', '蒙·拉瓦斯', 'モン・ラーバス', 'Normal Monster', 'Beast', 'EARTH', 4, 1300, 1400, '进化过的野兽。力量有相当的提高。'),
(59983249, 'Monarchic Perfection', '帝王的极致', '帝王の極致', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方把怪兽特殊召唤的场合1次，若自己场上有上级召唤的怪兽存在，可以从自己墓地把1张「帝王」魔法·陷阱卡除外，从以下选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●场上1只怪兽破坏。 ●场上最多2张魔法·陷阱卡破坏。 ●对方手卡随机1张丢弃。 ●场上1张里侧表示卡破坏。 ●场上1张卡回到卡组最上面。 ●场上1张卡除外。'),
(3810071, 'Monk Fighter', '武僧战士', 'モンク・ファイター', 'Effect Monster', 'Rock', 'EARTH', 3, 1300, 1000, '这张卡进行战斗使控制者受到的战斗伤害为0。'),
(32519092, 'Monk of the Tenyi', '天威之拳僧', '天威の拳僧', 'Link Monster', 'Wyrm', 'EARTH', NULL, 1000, NULL, '连接怪兽以外的「天威」怪兽1只'),
(56897896, 'Mono Synchron', '一星同调士', 'モノ・シンクロン', 'Tuner Monster', 'Machine', 'DARK', 1, NULL, NULL, '把这张卡作为同调素材的场合，其他的同调素材怪兽必须是4星以下的战士族·机械族怪兽，那些等级当作1星使用。'),
(58807980, 'Monoceros', '单角兽', 'モノケロース', 'Effect Monster', 'Beast', 'LIGHT', 3, 1000, 1000, '这张卡不能通常召唤。把手卡1张魔法卡从游戏中除外的场合可以特殊召唤。这张卡和兽族调整为素材的同调召唤成功时，可以把1只作为那次同调召唤的素材的兽族调整从墓地特殊召唤。'),
(23270035, 'Monster Assortment', '怪兽分类', 'モンスターアソート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选种族·属性·等级是相同的1只通常怪兽和1只效果怪兽给对方观看，对方从那之中随机选1只。那1只怪兽加入自己手卡，剩余回到卡组。'),
(36121917, 'Monster Egg', '怪兽蛋', 'モンスター・エッグ', 'Normal Monster', 'Warrior', 'EARTH', 3, 600, 900, '蛋壳保卫全身的迷之战士，用壳飞射攻击。'),
(637216, 'Monster Express', '怪兽快车', 'モンスターエクスプレス', 'Effect Monster', 'Machine', 'EARTH', 4, 1500, 1200, '这个卡名的效果1回合只能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能发动。原本种族和那只表侧表示怪兽相同的1只怪兽从额外卡组送去墓地。这个回合，自己若非这个效果送去墓地的怪兽以及原本种族和那只怪兽相同的怪兽则不能特殊召唤。'),
(84133008, 'Monster Eye', '眼球怪', 'モンスター・アイ', 'Effect Monster', 'Fiend', 'DARK', 1, 250, 350, '支付1000基本分发动。自己墓地存在的1张「融合」回到手卡。'),
(43040603, 'Monster Gate', '怪兽门', 'モンスターゲート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只怪兽解放才能发动。直到可以通常召唤的怪兽出现为止从自己卡组上面翻卡，那只怪兽特殊召唤。剩下的翻开的卡全部送去墓地。'),
(54564198, 'Monster Rebirth', '死者所生', '死者所生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：怪兽被战斗破坏的回合，从手卡·卡组把1张「死者苏生」送去墓地，以自己或者对方的墓地1只怪兽为对象才能发动。那只怪兽当作「死者苏生」的效果的特殊召唤在自己场上特殊召唤。'),
(60621361, 'Monster Rebone', '夺骨苏生', '横取りボーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方把怪兽特殊召唤的回合，以对方墓地1只怪兽为对象才能把这张卡发动。那只怪兽在自己场上守备表示特殊召唤。这张卡从场上离开时那只怪兽除外。那只怪兽从场上离开时这张卡破坏。'),
(83764719, 'Monster Reborn', '死者苏生', '死者蘇生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(50213848, 'Monster Reborn Reborn', '取舍苏生', '取捨蘇生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地3只怪兽为对象才能发动。对方从作为对象的怪兽之中选1只。那1只怪兽在自己场上特殊召唤，剩下的怪兽全部除外。'),
(93108433, 'Monster Recovery', '怪兽回收', 'モンスター回収', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择原本持有者是自己的自己场上1只怪兽才能发动。选择的怪兽和自己手卡全部加入卡组洗切。那之后，从卡组抽出原本的手卡数量的卡。原本持有者是对方的卡在自己手卡的场合，这张卡不能发动。'),
(74848038, 'Monster Reincarnation', '死者转生', '死者転生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以自己墓地1只怪兽为对象才能发动。那只怪兽加入手卡。'),
(9576193, 'Monster Slots', '怪兽角子机', 'モンスター・スロット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽，选择和选择的怪兽相同等级的自己墓地存在的1只怪兽从游戏中除外。那之后，从自己卡组抽1张卡。这个效果抽到的卡给双方确认，和选择的怪兽相同等级的怪兽的场合，那只怪兽特殊召唤。'),
(97612389, 'Monster Tamer', '地狱的魔物使', '地獄の魔物使い', 'Normal Monster', 'Warrior', 'EARTH', 5, 1800, 1600, '能自由自在地操纵怪兽攻击的怪兽使。'),
(35712107, 'Monstrous Bird', '巨大怪鸟', '巨大な怪鳥', 'Normal Monster', 'Winged Beast', 'WIND', 6, 2000, 1900, '很少见的大鸟。从空中急速下除袭击。'),
(15820147, 'Monsturtle', '怪龟', 'モンスタートル', 'Normal Monster', 'Aqua', 'WATER', 3, 800, 1000, '装备了带刺的甲壳的龟。非常凶暴不喜欢接近人类。'),
(23303072, 'Montage Dragon', '合成龙', 'モンタージュ・ドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 8, -1, NULL, '这张卡不能通常召唤。把手卡3张怪兽卡送去墓地的场合才能特殊召唤。这张卡的攻击力变成这张卡的特殊召唤时送去墓地的怪兽的等级合计×300的数值。'),
(14005031, 'Moon Dance Ritual', '月舞的仪式', 'ムーンダンスの儀式', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己场上1只没有超量素材的风属性超量怪兽为对象才能把这张卡发动。只要那只怪兽在场上存在，场上的表侧表示怪兽的效果无效化。作为对象的怪兽从场上离开时这张卡破坏。 ②：这张卡发动的回合的结束阶段发动。把场上的这张卡在这张卡的发动时作为对象的怪兽下面重叠作为超量素材。'),
(66818682, 'Moon Dragon Quilla', '月影龙 基利亚', '月影龍クイラ', 'Synchro Monster', 'Dragon', 'DARK', 6, 2500, 2000, '「苏帕伊」＋调整以外的怪兽1只以上 ①：这张卡被选择作为攻击对象的场合发动。自己基本分回复攻击怪兽的攻击力一半的数值。 ②：场上的这张卡被破坏的场合，以自己墓地1只「太阳龙 因蒂」为对象才能发动。那只怪兽特殊召唤。'),
(45909477, 'Moon Envoy', '月之使者', '月の使者', 'Normal Monster', 'Warrior', 'LIGHT', 4, 1100, 1000, '侍奉月之女神的战士。使用像新月一样的戈进行攻击！'),
(336601, 'Moon Gardna', '月之守卫者', 'ムーン・ガードナー', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 100, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：对方场上有怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，若对方场上有怪兽存在，以「月之守卫者」以外的自己墓地1只光属性·4星怪兽为对象才能发动。那只怪兽加入手卡。'),
(74941992, 'Moon Magician', '月之魔术师', '月の魔術師', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 1500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：对方场上有超量怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以「月之魔术师」以外的自己墓地1只光属性·4星怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(19508728, 'Moon Mirror Shield', '月镜盾', '月鏡の盾', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：这张卡的装备怪兽和对方怪兽进行战斗的伤害计算时发动。装备怪兽的攻击力·守备力只在伤害计算时变成进行战斗的对方怪兽的攻击力和守备力之内较高方的数值＋100。 ②：表侧表示的这张卡从场上送去墓地的场合，支付500基本分发动。这张卡回到卡组最上面或者最下面。'),
(71818935, 'Moon of the Closed Heaven', '闭月天女 南娜', '閉ザサレシ天ノ月', 'Link Monster', 'Fiend', 'LIGHT', NULL, 1200, NULL, '效果怪兽2只 这个卡名的效果1回合只能使用1次。 ①：以这张卡所连接区1只对方的表侧表示怪兽为对象才能发动。这个回合，自己用自己场上的这张卡为素材把连接5怪兽连接召唤的场合，作为对象的对方怪兽也能作为连接素材。'),
(97452818, 'Moon Token', '秘仪之力ⅩⅧ－月亮', 'アルカナフォースⅩⅧ－THE MOON', 'Token', 'Fairy', NULL, NULL, NULL, NULL, NULL),
(16366944, 'Moonlit Papillon', '月光蝶', '月光蝶', 'Effect Monster', 'Insect', 'LIGHT', 4, 1200, 1600, '这张卡从场上送去墓地时，可以从卡组把1只4星以下的名字带有「幻蝶刺客」的怪兽特殊召唤。'),
(58074572, 'Mooyan Curry', '魔族的咖喱', 'モウヤンのカレー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '回复200点基本分。'),
(93671934, 'Morale Boost', '士气高扬', '士気高揚', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每当1张装备魔法卡装备在怪兽身上时，这张装备魔法的控制者回复1000基本分。每当1张装备魔法卡离场时，这张装备魔法的控制者受到1000点伤害。'),
(73244186, 'Moray of Avarice', '贪欲之海鳝', '貪欲なウツボ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示的鱼族·海龙族·水族怪兽除外才能发动。自己抽2张。'),
(22123627, 'Moray of Greed', '强欲之海鳝', '強欲なウツボ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡让2只水属性怪兽回到卡组洗切。那之后，自己从卡组抽3张。'),
(12760674, 'Mordschlag', '剑柄杀击', 'モルトシュラーク', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的通常召唤的怪兽才能装备。 ①：装备怪兽不受特殊召唤的对方场上的怪兽发动的效果影响。 ②：装备怪兽和特殊召唤的对方怪兽进行战斗的伤害计算时发动。那只对方怪兽的攻击力·守备力只在那次伤害计算时下降装备怪兽的原本攻击力数值。'),
(38505587, 'Moremarshmallon', '棉棉花糖', 'マシマシュマロン', 'Effect Monster', 'Fairy', 'LIGHT', 3, 300, 500, '这个卡名的①③的效果1回合各能使用1次。 ①：对方回合，自己场上有「光之黄金柜」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：只要自己场上有「光之黄金柜」存在，这张卡不会被战斗破坏，对方怪兽不能选择其他怪兽作为攻击对象。 ③：这张卡被效果破坏的场合才能发动。除这张卡外的自己的手卡·卡组·墓地·除外状态的1只「增量棉花糖」特殊召唤，给与对方1000伤害。'),
(24027078, 'Morgan, the Enchantress of Avalon', '阿瓦隆的魔女 摩根', 'アヴァロンの魔女モルガン', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1300, 1600, '这个卡名的效果1回合只能使用1次。 ①：自己场上有「圣骑士」怪兽以及「圣剑」装备魔法卡存在，对方把魔法·陷阱·怪兽的效果发动时，把这张卡从手卡送去墓地才能发动。选自己场上1张「圣剑」装备魔法卡破坏，那个发动无效。'),
(29439831, 'Morgana the Witch of Eyes', '瞳之魔女 摩尔嘉娜', '瞳の魔女モルガナ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 2100, '这个卡名在规则上也当作「魔瞳」卡使用。这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「魔瞳」魔法卡加入手卡。 ②：对方怪兽的攻击宣言时，从自己墓地把1张「魔瞳」魔法卡除外才能发动。那次攻击无效。 ③：自己的墓地·除外状态的「魔瞳」魔法卡是3种类以上的场合才能发动。对方场上的全部怪兽的攻击力变成0。'),
(55784832, 'Morinphen', '莫林芬', 'モリンフェン', 'Normal Monster', 'Fiend', 'DARK', 5, 1550, 1300, '以长臂和钩爪为特征有着奇妙样貌的恶魔。'),
(71717923, 'Mormolith', '摩门', 'モーム', 'Effect Monster', 'Rock', 'EARTH', 4, 1000, 900, '把自己场上表侧表示存在的1只地属性怪兽解放发动。场上表侧表示存在持有解放怪兽的攻击力以下的守备力的怪兽全部破坏。'),
(85457355, 'Morph King Stygi-Gel', '变容王 狱胶', '変容王 ヘル・ゲル', 'Tuner Monster', 'Fiend', 'DARK', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。这张卡的等级变成和那只怪兽相同，自己回复那只怪兽的等级×200基本分。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。 ②：自己主要阶段才能发动。从手卡把持有比这张卡低的等级的1只恶魔族怪兽特殊召唤。'),
(38267552, 'Morpheus, the Dream Mirror Black Knight', '梦魔镜黑骑士－鲁耳甫斯', '夢魔鏡の黒騎士－ルペウス', 'Effect Monster', 'Warrior', 'DARK', 8, 2800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：场地区域有「圣光之梦魔镜」存在的场合，自己·对方的主要阶段以及战斗阶段，把这张卡解放才能发动。从卡组把1只「梦魔镜的白骑士-卢甫斯」特殊召唤。'),
(1872843, 'Morpheus, the Dream Mirror White Knight', '梦魔镜白骑士－鲁耳甫斯', '夢魔鏡の白騎士－ルペウス', 'Effect Monster', 'Warrior', 'LIGHT', 8, 1000, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合才能发动。这个回合，这张卡不会被战斗·效果破坏。 ②：场地区域有「黯黑之梦魔镜」存在的场合，自己·对方的主要阶段以及战斗阶段，把这张卡解放才能发动。从卡组把1只「梦魔镜的黑骑士-卢甫斯」特殊召唤。'),
(33508719, 'Morphing Jar', '变形壶', 'メタモルポット', 'Flip Effect Monster', 'Rock', 'EARTH', 2, 700, 600, '①：这张卡反转的场合发动。有手卡的玩家把那些手卡全部丢弃。双方从卡组抽5张。'),
(79106360, 'Morphing Jar #2', '混沌壶', 'カオスポッド', 'Flip Effect Monster', 'Rock', 'EARTH', 3, 800, 700, '反转：场上的怪兽全部加入持有者卡组洗切。那之后，双方玩家直到和加入各自卡组的数量相同数量的怪兽出现为止把卡组翻开，从那之中把4星以下的怪兽全部里侧守备表示特殊召唤。那以外的翻开的卡全部丢弃去墓地。'),
(43573231, 'Morpho Butterspy', '幻蝶刺客 闪蝶', '幻蝶の刺客モルフォ', 'Effect Monster', 'Warrior', 'DARK', 4, 1200, 1600, '对方场上的怪兽的表示形式变更时，选择那1只怪兽才能发动。选择的怪兽的攻击力·守备力下降1000。这个效果1回合只能使用1次。'),
(92890308, 'Morphtransition', '变形', 'ディフォーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「变形斗士」的怪兽被选择作为攻击对象时才能发动。把1只攻击怪兽的攻击无效，被选择作为攻击对象的1只名字带有「变形斗士」的怪兽的表示形式改变。'),
(44424095, 'Morphtronic Accelerator', '变形斗士·加速装置', 'D・スピードユニット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡让1只名字带有「变形斗士」的怪兽回到卡组。场上1张卡破坏，从自己卡组抽1张卡。'),
(85101228, 'Morphtronic Bind', '变形斗士·电网', 'D・バインド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要自己场上有名字带有「变形斗士」的怪兽表侧表示存在，对方场上存在的4星以上的怪兽不能攻击宣言，也不能把表示形式改变。'),
(48381268, 'Morphtronic Boarden', '变形斗士·滑板', 'D・ボードン', 'Effect Monster', 'Machine', 'EARTH', 3, 500, 1800, '①：这张卡得到表示形式的以下效果。 ●攻击表示：只要这张卡在怪兽区域存在，自己的「变形斗士」怪兽可以直接攻击。 ●守备表示：只要这张卡在怪兽区域存在，这张卡以外的自己的「变形斗士」怪兽不会被战斗破坏。'),
(92720564, 'Morphtronic Boomboxen', '变形斗士·收录机', 'D・ラジカッセン', 'Effect Monster', 'Machine', 'EARTH', 4, 1200, 400, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：这张卡在同1次的战斗阶段中可以作2次攻击。 ●守备表示：自己场上表侧表示存在的名字带有「变形斗士」的怪兽被选择作为攻击对象时，可以把那次战斗无效。这个效果1回合只能使用1次。'),
(28124263, 'Morphtronic Cameran', '变形斗士·照相机', 'D・キャメラン', 'Effect Monster', 'Machine', 'LIGHT', 2, 800, 600, '这张卡得到这张卡的表示形式的以下效果。 ●攻击表示：这张卡被战斗破坏时，可以把自己的手卡·墓地存在的「变形斗士·照相机」以外的1只名字带有「变形斗士」的4星以下的怪兽在自己场上特殊召唤。 ●守备表示：只要这张卡在场上表侧表示存在，名字带有「变形斗士」的怪兽不能成为魔法·陷阱·效果怪兽的效果的对象。');